async function guard(fn){if(busy)return false;busy=true;busyControls=new Map();const serial=sessionSerial;lockBusyControls();document.body.setAttribute('aria-busy','true');try{if(!connected)throw Error('目前未連線 Firebase，請恢復網路後再操作');if(!uid||!ready)throw Error('資料尚未完成同步，請稍候；若持續出現請檢查權限與網路');await fn();if(serial!==sessionSerial)throw Error('登入狀態已變更，操作結果請回原帳號確認');clearErrors();return true}catch(e){fail(e);return false}finally{busy=false;for(const [n,disabled] of busyControls)if(n.isConnected)n.disabled=disabled;busyControls=null;document.body.removeAttribute('aria-busy');$('mergeCommit').disabled=!mergePreviewState||!$('mergeAcknowledged').checked}}
function rootRef(){if(!uid||auth.currentUser?.uid!==uid)throw Error('登入已失效，請重新登入');return db.ref('users/'+uid)}
async function transact(fn){const serial=sessionSerial;let problem;const result=await rootRef().transaction(state=>{problem=null;try{return fn(state)}catch(e){problem=e;return}},undefined,false);if(serial!==sessionSerial)throw Error('登入狀態已變更，操作結果請回原帳號確認');if(!result.committed)throw problem||Error('資料有衝突，未儲存，請重試');return result}
function operationId(){return db.ref().push().key}
async function saveOrder(id,next,old,selection,operation){let mappingPreview=null;if(next?.shipped&&management.inventory?.mappingMode&&!(old?.shipped&&management.inventory?.legacyExempt?.[id])){mappingPreview=C.shipmentPlan(management,next,old?.shipped?management.inventory.orderSnapshots?.[id]:null);if(!old?.shipped||!C.sameItems(old,next)){if(!confirm("出貨實體庫存預覽（含贈品）：\n"+Object.entries(mappingPreview.totals).map(([pid,n])=>(inventoryProducts()[pid]?.name||pid)+"："+n+" 包").join("\n")+"\n確認依此明細出貨？"))throw Error("已取消出貨，資料未修改");}}let stockReturned=false;if(old?.shipped&&(!next?.shipped||!C.sameItems(old,next))){if(!confirm("此操作涉及已出貨商品。確認減少的商品已實際放回冷凍庫且可再販售？未回庫請取消並使用取消／退貨紀錄。"))throw Error("已取消變更；訂單與庫存未修改");stockReturned=true;}const key=operation||operationId(),riskExpected=JSON.parse(JSON.stringify(management.customerRisk?.records||{}));await transact(s=>{if(next&&!old&&!C.equalLegacy(s?.customerRisk?.records||{},riskExpected))throw Error('黑名單資料已更新，請重新核對提醒後再儲存');return selection?C.applyCustomerOrder(s,id,next,old,key,op,firebase.database.ServerValue.TIMESTAMP,selection,{mappingPreview}):C.applyOrder(s,id,next,old,key,op,firebase.database.ServerValue.TIMESTAMP,{stockReturned,mappingPreview})})}

