 customerSelection=null;mergePreviewState=null;orderDraft=null;$('orderCustomerQuery').value='';$('orderCustomerResults').textContent='';$('orderCustomerSearchStatus').textContent='';$('customerMatchOptions').textContent='';$('mergePreview').textContent='';$('mergeSource').innerHTML='';$('mergeTarget').innerHTML='';
 subscriptions.forEach(([r,f])=>r.off('value',f));subscriptions=[];ready=false;uid='';orders={};products={};management={};selectedCustomer='';customerEditorDirty=false;sessionUser=u?.uid||'';$('customerDetail').innerHTML='';resetExpense();inventoryProductSignature='';inventoryDraft=null;inventoryPending=null;initPending=null;productStockDraft=null;stockItemDraft=null;stockBatchPending=null;stockBatchSignature='';inventoryView='home';inventoryNavigate('home',true);categorySignature='';resetShrimp();$('managementError').classList.add('hidden');
