$('productSubmit').insertAdjacentHTML('beforebegin','<fieldset id="productStockFields"><legend>這個商品要扣哪個庫存？</legend><p class="management-help">這裡設定銷售商品與實體料理包的關係，不會改動歷史訂單或過去出貨。</p><label>庫存方式<select id="productStockMode"><option value="">請明確選擇</option><option value="shared">共用既有庫存</option><option value="new">建立新的獨立庫存</option><option value="combo">組合商品（扣多個實體品項）</option></select></label><div id="productSharedBox"><label>實體庫存<select id="productStockShared"></select></label><label>每銷售／贈送一單位扣幾包<input id="productStockQty" type="number" min="1" step="1" value="1"></label></div><div id="productNewBox" class="hidden"><label>新實體庫存名稱<input id="productStockName" placeholder="例如：大隻檸檬蝦"></label></div><div id="productComboBox" class="hidden"><div id="productStockLines"></div><button type="button" id="productStockAdd">新增實體品項</button></div><p>不同售價的相同料理包，請選同一實體庫存；雙拼等組合請逐項填寫扣除包數。</p></fieldset>');
let productStockDraft=null;
function stockSelectOptions(selected=''){return '<option value="">請選擇實體庫存</option>'+Object.entries(C.physicalItems(management)).filter(([id,p])=>p.active!==false||id===selected).map(([id,p])=>'<option value="'+esc(id)+'" '+(id===selected?'selected':'')+'>'+esc(p.name)+'</option>').join('')}
function productStockMode(){const m=$('productStockMode').value;$('productSharedBox').classList.toggle('hidden',m!=='shared');$('productNewBox').classList.toggle('hidden',m!=='new');$('productComboBox').classList.toggle('hidden',m!=='combo')}
function productComponent(id='',qty=''){const row=document.createElement('div');row.className='stock-component-row';row.innerHTML='<label>實體庫存<select>'+stockSelectOptions(id)+'</select></label><label>每單位包數<input type="number" min="1" step="1"></label><button type="button">移除</button>';row.querySelector('input').value=qty;row.querySelector('button').onclick=()=>row.remove();$('productStockLines').append(row)}
function loadProductStock(id){const p=products[id]||null,m=management.inventory?.productMappings?.[id]||null;productStockDraft={id:id||operationId(),operation:operationId(),newItemId:operationId(),expectedProduct:p?JSON.parse(JSON.stringify(p)):null,expectedMapping:m?JSON.parse(JSON.stringify(m)):null,pending:null};$('productStockShared').innerHTML=stockSelectOptions();$('productStockName').value='';$('productStockQty').value='1';$('productStockLines').textContent='';const rows=Object.entries(m?.components||{});$('productStockMode').value=rows.length===1?'shared':rows.length>1?'combo':'';if(rows.length===1){$('productStockShared').value=rows[0][0];$('productStockQty').value=rows[0][1]}else if(rows.length>1)for(const [pid,q] of rows)productComponent(pid,q);productStockMode()}
const resetProductBeforeStock=resetProductForm;resetProductForm=function(){resetProductBeforeStock();loadProductStock()};$('productCancel').onclick=()=>{if(!busy)resetProductForm()};const editProductBeforeStock=window.editProduct;window.editProduct=id=>{if(busy)return;editProductBeforeStock(id);loadProductStock(id)};
$('productStockMode').onchange=()=>{if($('productStockMode').value==='combo'&&!$('productStockLines').children.length)productComponent();productStockMode()};$('productStockAdd').onclick=()=>productComponent();
$('productForm').onsubmit=e=>{e.preventDefault();guard(async()=>{const draft=productStockDraft;if(!draft)throw Error('請重新開啟商品');const mode=$('productStockMode').value,components={};let newItem;
 if(mode==='shared'){if(!$('productStockShared').value)throw Error('請選擇實體庫存');components[$('productStockShared').value]=$('productStockQty').value}
 else if(mode==='new'){newItem={id:draft.newItemId,name:$('productStockName').value};components[draft.newItemId]=1}
 else if(mode==='combo'){for(const row of $('productStockLines').children){const id=row.querySelector('select').value;if(!id||Object.prototype.hasOwnProperty.call(components,id))throw Error('請選擇各實體品項，同一品項勿重複');components[id]=row.querySelector('input').value}}
 else throw Error('請明確設定此商品的庫存對應');
 const request={kind:'productMapping',id:draft.id,expectedProduct:draft.expectedProduct,expectedMapping:draft.expectedMapping,product:{name:$('pname').value.trim(),price:$('pprice').value},components,...(newItem?{newItem}:{})};if(draft.pending&&!C.equalLegacy(draft.pending,request))throw Error('上次儲存結果尚未確認，請以原內容重試並核對');C.configureInventory(management,request,draft.operation,op,Date.now());draft.pending=request;await transact(s=>C.configureInventory(s,request,draft.operation,op,firebase.database.ServerValue.TIMESTAMP));resetProductForm()})};


