 $('customerDetail').innerHTML='<div class="customer-summary management-grid">'+[['有效下單次數',(customerStats().find(x=>x.id===c.id)?.effectiveCount||0)+' 次'],['累積下單金額（非實收）',money(customerStats().find(x=>x.id===c.id)?.orderAmount||0)],['首次購買',dateText(c.first)],['最近購買',dateText(c.last)]].map(([label,value])=>'<div class="card">'+label+'<strong>'+esc(value)+'</strong></div>').join('')+'</div>'+(c.orders.some(o=>!o.createdAt)?'<p class="management-help">另含建立日期不明的舊訂單，未虛構日期。</p>':'')+'<p class="management-help">聯絡管道：'+esc(c.channels.map(x=>x.platform+' '+x.account).join('、'))+'<br>原始客戶 ID：'+esc(c.sourceIds.join('、'))+'</p><form id="customerEdit"><h3>基本資料</h3>'+[['name','客戶姓名'],['phoneLast3','手機後三碼（舊客戶可留白）'],['phone','電話（選填）'],['contactType','訂購／聯絡平台'],['contactAccount','聯絡帳號'],['delivery','常用取貨方式'],['deliveryDetail','常用取貨地點'],['notes','備註']].map(([id,label])=>customerField(id,label,c)).join('')+'<button type="submit" class="primary">儲存基本資料</button></form><h3>歷史訂單與購買商品</h3><div class="customer-history">'+(c.orders.map(o=>'<p>訂單 '+esc(o.id)+' · '+(management.inventory?.orderStates?.[o.id]?.cancelled?'已取消／不計有效單 · ':'')+(management.deliveryExceptions?.cases?.[o.id]?'未成功取貨 · ':'')+esc(dateText(o.createdAt))+' · '+money(C.total(o))+' · '+esc(C.items(o).map(i=>(i.productName||'未填商品名')+' × '+(+i.qty||0)+'（贈 '+(+i.gift||0)+'）').join('、'))+'</p>').join('')||'<p>尚無訂單</p>')+'</div>';
 $('customerEdit').oninput=()=>{customerEditorDirty=true;$('customerNotice').textContent='有尚未儲存的修改'};
