$('openCustomerMerge').onclick=()=>{try{const all=customers();if(all.length<2)throw Error('至少需要兩位未合併的客戶');const options=all.map(c=>'<option value="'+esc(c.id)+'">'+esc(c.name)+' '+esc(c.phoneLast3||'未記錄')+' · '+esc(c.id)+'</option>').join('');$('mergeSource').innerHTML=options;$('mergeTarget').innerHTML=options;$('mergeTarget').selectedIndex=1;invalidateMergePreview();openActionDialog('customerMergeDialog')}catch(e){fail(e)}};
