function renderMergeHistory(){$('customerMergeHistory').innerHTML=Object.entries(management.customerMergeHistory||{}).sort((a,b)=>(+b[1].date||0)-(+a[1].date||0)).map(([id,h])=>'<article class="card">'+esc(h.sourceSnapshot?.name||h.sourceId)+' → '+esc(h.targetSnapshot?.name||h.targetId)+'<br>'+dateText(h.date)+' · '+esc(h.operator)+' · '+(h.status==='active'?'<button type="button" data-undo-merge="'+esc(id)+'">解除此合併</button>':'已解除 · '+dateText(h.reversedAt))+'</article>').join('')||'<p>尚無合併紀錄</p>';$('customerMergeHistory').querySelectorAll('[data-undo-merge]').forEach(b=>b.onclick=()=>{if(confirm('解除合併只拆開客戶對照，所有訂單保留；合併後新建訂單仍屬於當時選定的保留客戶。確定解除？'))guard(()=>transact(s=>C.undoCustomerMerge(s,b.dataset.undoMerge,op,firebase.database.ServerValue.TIMESTAMP)))})}


// Inventory pages share the original product IDs; drafts never write before submit.
$('panel-inventory').innerHTML='<h2>冷凍庫存管理</h2><p id="inventoryNotice" role="status"></p><nav class="inventory-actions"><button data-inv-go="home">庫存首頁</button><button data-inv-go="receipt">製作／入庫</button><button data-inv-go="stats">製作統計</button><button data-inv-go="adjust">盤點／報廢</button><button data-inv-go="history">歷史紀錄</button></nav><details class="card" id="stockSetup"><summary>實體庫存與商品對應設定</summary><p>先建立檸檬蝦、胡椒蝦等實體品項，再逐一編輯銷售商品，指定共用或組合對應。系統不依名稱自動套用。</p><form id="stockItemForm"><label>新實體庫存名稱<input id="stockItemName" placeholder="例如：檸檬蝦"></label><button class="primary">建立實體庫存</button></form><div id="stockMappingList"></div><details><summary>手動指定多個商品共用庫存</summary><p>請自行勾選相同實物的商品。系統不會按名稱自動勾選。</p><div id="stockBatchChoices"></div><label>共用哪個實體庫存<select id="stockBatchTarget"></select></label><label>每銷售／贈送一單位扣幾包<input id="stockBatchQty" type="number" min="1" step="1" value="1"></label><button type="button" id="stockBatchSave">預覽並確認共用對應</button></details><button type="button" id="stockOpenProducts">開啟商品管理設定對應</button></details><p id="inventoryBaseline"></p><p id="inventoryDemandWarning" class="management-error hidden" role="alert"></p><section data-inv-view="home"><div id="inventoryList" class="inventory-cards"></div><form id="inventoryInit" class="card"><h3>首次盤點與啟用</h3><p>尚未啟用時暫停出貨。請先關閉其他裝置舊分頁，暫停出貨並輸入冷凍庫目前實際包數；期初不列入製作統計、不補扣歷史已出貨單。</p><div id="inventoryCounts"></div><button class="primary">預覽並確認啟用</button></form></section><section data-inv-view="receipt" class="hidden"><h3 id="receiptTitle">新增製作／入庫</h3><form id="inventoryReceipt"><label>類型<select id="receiptType"><option value="production">料理包製作（列製作統計）</option><option value="inbound">其他入庫（不列製作統計）</option></select></label><label>製作／入庫日期<input id="receiptDate" type="date" required></label><p class="management-help">不得補登已含期初現貨的製作。日期不明的期初現貨不推測製作日期。</p><div id="receiptLines"></div><button type="button" id="receiptAdd">新增商品</button><label>備註<textarea id="receiptNotes"></textarea></label><div class="inventory-form-actions"><button class="primary">儲存入庫</button><button type="button" data-inv-go="home">取消／返回</button></div></form></section><section data-inv-view="stats" class="hidden"><h3>製作數量統計</h3><div class="row"><button data-stat-period="day">今日</button><button data-stat-period="month">本月</button></div><label>月份<input type="month" id="productionMonth"></label><div class="row"><label>開始日期<input type="date" id="productionStart"></label><label>結束日期<input type="date" id="productionEnd"></label></div><p>依製作日期加總有效製作紀錄；期初、其他入庫、退貨、盤點及報廢不列入。報廢不減少曾實際製作數量。</p><div id="productionTotals"></div><div id="productionDaily"></div><button id="productionCsv">匯出製作 CSV</button></section><section data-inv-view="adjust" class="hidden"><h3>盤點／報廢／其他調整</h3><form id="stockForm"><label>商品<select id="stockProduct"></select></label><label>方式<select id="stockMode"><option value="delta">數量增減（報廢填負數）</option><option value="count">盤點實際包數（新商品先用此方式）</option></select></label><label>包數<input id="stockQty" required type="number" step="1"></label><label>原因<input id="stockReason" required placeholder="破包、報廢、試吃、盤點…"></label><p>盤點以開啟表單時庫存為準；其他裝置更新後需重新開啟確認。</p><div class="inventory-form-actions"><button class="primary">確認調整</button><button type="button" data-inv-go="home">返回</button></div></form></section><section data-inv-view="history" class="hidden"><h3>製作與入庫紀錄</h3><label>搜尋商品／原因／備註<input id="inventorySearch" type="search"></label><div class="row"><label>開始日期<input type="date" id="inventoryHistoryStart"></label><label>結束日期<input type="date" id="inventoryHistoryEnd"></label></div><label>商品<select id="inventoryHistoryProduct"><option value="">全部商品</option></select></label><div id="receiptHistory"></div><h3>所有庫存異動</h3><div id="movementList"></div><h3>操作追溯</h3><div id="inventoryAudit"></div></section>';
let inventoryProductSignature='',inventoryView='home',inventoryDraft=null,inventoryInitial='',inventoryPending=null,stockExpected=null,stockInitial='',initPending=null,adjustOperation=null,adjustPending=null;
function salesProducts(){const p={...products};Object.values(orders).forEach(o=>C.items(o).forEach(i=>{if(i.productId&&!p[i.productId])p[i.productId]={name:(i.productName||i.productId)+'（歷史商品）',active:false}}));return p}
function inventoryProducts(){return C.physicalItems(management)}
function inventoryOptions(){return Object.entries(inventoryProducts()).map(([id,p])=>'<option value="'+esc(id)+'">'+esc(p.name)+(p.active===false?'（下架）':'')+'</option>').join('')}
function inventoryDirty(){return inventoryView==='receipt'&&formSnapshot($('inventoryReceipt'))!==inventoryInitial||inventoryView==='adjust'&&formSnapshot($('stockForm'))!==stockInitial}
function allowInventoryLeave(){if(busy){fail(Error('操作尚未完成，請稍候'));return false}if(inventoryDirty()&&!confirm('庫存表單尚未儲存，確定放棄？'))return false;return true}
function inventoryNavigate(view,force=false){if(!force&&!allowInventoryLeave())return false;inventoryView=view;$('panel-inventory').querySelectorAll('[data-inv-view]').forEach(p=>p.classList.toggle('hidden',p.dataset.invView!==view));if(view==='receipt'&&!force)resetInventoryReceipt();if(view==='adjust'){adjustOperation=operationId();adjustPending=null;stockExpected=management.inventory?.stock?.[$('stockProduct').value]??null;stockInitial=formSnapshot($('stockForm'))}renderInventory();window.scrollTo(0,0);return true}
function receiptLine(line={}){const row=document.createElement('div');row.className='inventory-receipt-line';row.innerHTML='<label>商品<select data-receipt-product>'+inventoryOptions()+'</select></label><label>完成包數<input data-receipt-qty type="number" min="1" step="1" required></label><button type="button">移除</button>';if(line.productId)row.querySelector('select').value=line.productId;row.querySelector('input').value=line.quantity||'';row.querySelector('button').onclick=()=>{if($('receiptLines').children.length>1)row.remove()};$('receiptLines').append(row)}
function resetInventoryReceipt(id,expected){inventoryDraft={id:id||operationId(),operation:operationId(),expected:expected?JSON.parse(JSON.stringify(expected)):null};inventoryPending=null;$('inventoryReceipt').reset();$('receiptTitle').textContent=id?'編輯製作／入庫':'新增製作／入庫';$('receiptDate').value=expected?.date||localDate();$('receiptType').value=expected?.kind||'production';$('receiptNotes').value=expected?.notes||'';$('receiptLines').textContent='';for(const line of Object.values(expected?.lines||{one:{}}))receiptLine(line);inventoryInitial=formSnapshot($('inventoryReceipt'))}
async function writeInventory(request,operation){await transact(s=>C.applyInventory(s,request,operation,op,firebase.database.ServerValue.TIMESTAMP))}
function renderInventory(){const inv=management.inventory||{},all=inventoryProducts(),reserved=C.inventoryDemand(orders,inv),issues=C.inventoryDemandIssues(orders,inv);$('inventoryDemandWarning').classList.toggle('hidden',!issues.length);$('inventoryDemandWarning').textContent=issues.length?'有 '+issues.length+' 筆舊訂單商品資料待核對；需求只顯示可辨識部分，可用庫存暫不計算。請逐筆檢查：'+issues.map(i=>i.orderId+'（'+i.message+'）').join('、'):'';$('inventoryBaseline').textContent=inv.initializedAt?'期初基準：'+dateText(inv.initializedAt)+(inv.activation?.version>=2?' · 庫存新版已啟用':' · 舊版庫存沿用；不重新初始化'):'尚未啟用：請暫停出貨並完成首次盤點';$('inventoryInit').classList.toggle('hidden',!!inv.initializedAt);$('stockMappingList').innerHTML=Object.entries(salesProducts()).map(([id,p])=>{const m=inv.productMappings?.[id];return '<p><b>'+esc(p.name)+'</b> → '+(m?Object.entries(m.components).map(([sid,q])=>esc(inv.items?.[sid]?.name||sid)+' × '+q+' 包').join('＋'):'<strong class="danger">尚未設定</strong>')+'</p>'}).join('');
 $('inventoryList').innerHTML=Object.entries(all).map(([id,p])=>{const counted=!!inv.initializedAt&&C.hasOwn(inv.stock||{},id),n=Number(inv.stock?.[id]),held=reserved[id]||0;return '<article class="card inventory-product"><h3>'+esc(p.name)+(p.active===false?'（下架）':'')+'</h3><dl><div><dt>冷凍庫實際</dt><dd>'+ (counted?n+' 包':'未盤點')+'</dd></div><div><dt>待出貨（含贈品）</dt><dd>'+held+' 包</dd></div><div><dt>可用庫存</dt><dd>'+ (counted&&!issues.length?(n-held)+' 包':issues.length?'待核對':'—')+'</dd></div></dl>'+(counted&&n-held<0?'<p class="danger">尚需製作 '+(held-n)+' 包</p>':'')+'</article>'}).join('');
 const batchSignature=JSON.stringify({all,products:salesProducts(),mappings:inv.productMappings||{}});if(batchSignature!==stockBatchSignature){stockBatchSignature=batchSignature;stockBatchExpected=JSON.parse(JSON.stringify({products:products,mappings:inv.productMappings||{}}));const checked=new Set([...$('stockBatchChoices').querySelectorAll('input:checked')].map(x=>x.value)),target=$('stockBatchTarget').value;$('stockBatchChoices').innerHTML=Object.entries(salesProducts()).map(([id,p])=>'<label><input type="checkbox" value="'+esc(id)+'" '+(checked.has(id)?'checked':'')+'>'+esc(p.name)+'</label>').join('');$('stockBatchTarget').innerHTML=stockSelectOptions(target);}
 const sig=JSON.stringify(all);if(sig!==inventoryProductSignature){inventoryProductSignature=sig;const selected=$('stockProduct').value,values=Object.fromEntries([...document.querySelectorAll('[data-stock]')].map(x=>[x.dataset.stock,x.value]));$('inventoryCounts').innerHTML=Object.entries(all).map(([id,p])=>'<label>'+esc(p.name)+'<input data-stock="'+esc(id)+'" required type="number" min="0" step="1" value="'+esc(values[id]||'')+'" placeholder="目前實際包數"></label>').join('');$('stockProduct').innerHTML=inventoryOptions();if(all[selected])$('stockProduct').value=selected;const hp=$('inventoryHistoryProduct').value;$('inventoryHistoryProduct').innerHTML='<option value="">全部商品</option>'+inventoryOptions();if(all[hp])$('inventoryHistoryProduct').value=hp;}
 const query=$('inventorySearch').value.trim().toLowerCase(),historyStart=$('inventoryHistoryStart').value,historyEnd=$('inventoryHistoryEnd').value,historyProduct=$('inventoryHistoryProduct').value,inHistory=(date)=>!historyStart&&!historyEnd||C.validDate(date)&&(!historyStart||date>=historyStart)&&(!historyEnd||date<=historyEnd),receipts=Object.entries(inv.receipts||{}).sort((a,b)=>b[1].date.localeCompare(a[1].date));$('receiptHistory').innerHTML=receipts.filter(([,r])=>inHistory(r.date)&&(!historyProduct||Object.values(r.lines).some(l=>l.productId===historyProduct))&&(r.notes+' '+Object.values(r.lines).map(l=>l.productName).join(' ')).toLowerCase().includes(query)).map(([id,r])=>'<article class="card"><b>'+esc(r.date)+' · '+(r.kind==='production'?'製作':'其他入庫')+' · '+(r.status==='void'?'已作廢':'有效')+'</b><p>'+Object.values(r.lines).map(l=>esc(l.productName)+' '+l.quantity+' 包').join('、')+'</p><p>'+esc(r.notes)+'</p>'+(r.status==='active'?'<button data-receipt-edit="'+esc(id)+'">查看／編輯</button><button data-receipt-void="'+esc(id)+'">作廢</button>':'')+'</article>').join('')||'<p>尚無紀錄</p>';
 $('receiptHistory').querySelectorAll('[data-receipt-edit]').forEach(b=>{const snapshot=JSON.parse(JSON.stringify(inv.receipts[b.dataset.receiptEdit]));b.onclick=()=>{if(!allowInventoryLeave())return;resetInventoryReceipt(b.dataset.receiptEdit,snapshot);inventoryNavigate('receipt',true)}});
 $('receiptHistory').querySelectorAll('[data-receipt-void]').forEach(b=>{const id=b.dataset.receiptVoid,r=JSON.parse(JSON.stringify(inv.receipts[id]));b.onclick=()=>{if(!confirm('作廢會沖銷此筆入庫，保留原紀錄；庫存不足時不能沖銷。確定？'))return;const request={kind:'receipt',id,expected:r,type:r.kind,date:r.date,lines:Object.values(r.lines),notes:r.notes,void:true},key=operationId();guard(()=>writeInventory(request,key))}});
 $('movementList').innerHTML=Object.values(management.inventoryMovements||{}).filter(m=>(!historyProduct||m.productId===historyProduct)&&inHistory(Number(m.date)>0?localDate(Number(m.date)):'')&&(String(all[m.productId]?.name||m.productId)+' '+m.reason).toLowerCase().includes(query)).sort((a,b)=>(+b.date||0)-(+a.date||0)).map(m=>'<article class="card">'+esc(dateText(m.date))+' · '+esc(all[m.productId]?.name||m.productId)+' · '+(m.quantity>0?'+':'')+m.quantity+' 包<br>'+esc(m.reason)+' · '+esc(m.operator)+(m.orderId?' · 訂單 '+esc(m.orderId):'')+'</article>').join('')||'<p>尚無異動</p>';
 $('inventoryAudit').innerHTML=Object.entries(management.inventoryOperations||{}).filter(([,o])=>o.request).sort((a,b)=>(+b[1].date||0)-(+a[1].date||0)).map(([id,o])=>'<details class="card"><summary>'+esc(dateText(o.date))+' · '+esc(o.request.kind)+' · '+esc(o.operator)+'</summary><pre>'+esc(JSON.stringify(o.request,null,2))+'</pre></details>').join('');renderProductionStats();
}
function renderProductionStats(){const start=$('productionStart').value,end=$('productionEnd').value;if(!C.validDate(start)||!C.validDate(end)||start>end){$('productionTotals').textContent='請選擇有效日期區間';$('productionDaily').textContent='';return}const stats=C.inventoryStats(management.inventory,start,end);$('productionTotals').innerHTML=stats.products.map(p=>'<article class="card"><b>'+esc(p.name)+'</b> · 累計 '+p.quantity+' 包</article>').join('')||'<p>此期間無製作紀錄</p>';$('productionDaily').innerHTML=Object.entries(stats.daily).sort(([a],[b])=>a.localeCompare(b)).map(([date,rows])=>'<article class="card"><b>'+esc(date)+'</b><p>'+Object.entries(rows).map(([pid,n])=>esc(stats.products.find(p=>p.productId===pid)?.name||pid)+' '+n+' 包').join('、')+'</p></article>').join('')}
let stockBatchSignature='',stockBatchExpected=null,stockBatchPending=null;
$('stockBatchSave').onclick=()=>guard(async()=>{const id=$('stockBatchTarget').value;if(!id)throw Error('請明確選擇共用庫存');const entries=[...$('stockBatchChoices').querySelectorAll('input:checked')].map(x=>({id:x.value,expectedProduct:stockBatchExpected.products[x.value]||null,expectedMapping:stockBatchExpected.mappings[x.value]||null})),request={kind:'mappingBatch',entries,components:{[id]:$('stockBatchQty').value}};if(!entries.length)throw Error('請勾選要設定的商品');if(stockBatchPending&&!C.equalLegacy(stockBatchPending.request,request))throw Error('上次批次設定尚未確認，請先核對結果');if(!confirm('確認下列商品共用 '+(inventoryProducts()[id]?.name||id)+'，每單位 '+$('stockBatchQty').value+' 包？\n'+entries.map(e=>salesProducts()[e.id]?.name||e.id).join('\n')+'\n不改商品售價、不改歷史出貨。'))return;const draft=stockBatchPending||{request,operation:operationId()};C.configureInventory(management,request,draft.operation,op,Date.now());stockBatchPending=draft;await writeInventory(request,stockBatchPending.operation);stockBatchPending=null;$('inventoryNotice').textContent='已儲存人工確認的共用對應，原商品價格未修改';});
let stockItemDraft=null;$('stockItemForm').onsubmit=e=>{e.preventDefault();guard(async()=>{const name=$('stockItemName').value.trim(),draft=stockItemDraft||{id:operationId(),operation:operationId(),name};if(draft.name!==name)throw Error('前次建立尚未確認，請以原名稱重試');const request={kind:'stockItem',id:draft.id,name,expected:null};C.configureInventory(management,request,draft.operation,op,Date.now());stockItemDraft=draft;await writeInventory(request,draft.operation);stockItemDraft=null;$('stockItemName').value='';$('inventoryNotice').textContent='實體庫存已建立，請編輯銷售商品設定對應'})};$('stockOpenProducts').onclick=()=>{resetProductForm();openActionDialog('pd')};
$('receiptAdd').onclick=()=>{if(!busy)receiptLine()};$('inventorySearch').oninput=renderInventory;for(const id of ['inventoryHistoryStart','inventoryHistoryEnd','inventoryHistoryProduct'])$(id).onchange=renderInventory;
$('inventoryReceipt').onsubmit=e=>{e.preventDefault();guard(async()=>{if(!inventoryDraft)throw Error('請重新開啟入庫表單');const request={kind:'receipt',id:inventoryDraft.id,expected:inventoryDraft.expected,type:$('receiptType').value,date:$('receiptDate').value,notes:$('receiptNotes').value,lines:[...$('receiptLines').children].map(r=>({productId:r.querySelector('select').value,quantity:r.querySelector('input').value}))};if(inventoryPending&&!C.equalLegacy(inventoryPending,request))throw Error('前次儲存結果尚未確認，請用原內容重試並核對紀錄');C.applyInventory(management,request,inventoryDraft.operation,op,Date.now());inventoryPending=request;await writeInventory(request,inventoryDraft.operation);inventoryInitial=formSnapshot($('inventoryReceipt'));inventoryNavigate('home',true);$('inventoryNotice').textContent='入庫已儲存，庫存與製作統計已更新';inventoryDraft=null;inventoryPending=null})};
$('inventoryInit').onsubmit=e=>{e.preventDefault();guard(async()=>{const stock={};document.querySelectorAll('[data-stock]').forEach(x=>{if(!x.value)throw Error('請完整輸入各商品實際包數');stock[x.dataset.stock]=Number(x.value)});const request={kind:'activate',stock,expectedMappings:JSON.parse(JSON.stringify(management.inventory?.productMappings||{}))};if(initPending&&!C.equalLegacy(initPending.request,request))throw Error('前次啟用結果尚未確認，請先重新同步核對');if(!confirm('期初盤點預覽：\n'+Object.entries(stock).map(([id,n])=>(inventoryProducts()[id]?.name||id)+'：'+n+' 包').join('\n')+'\n確認所有裝置已更新並暫停出貨？完成後才開放出貨扣庫。'))return;initPending||={request,operation:operationId()};await writeInventory(request,initPending.operation);initPending=null;$('inventoryNotice').textContent='期初盤點完成；未補扣歷史已出貨單，現在可出貨'})};
$('stockProduct').onchange=()=>{adjustOperation=operationId();adjustPending=null;stockExpected=management.inventory?.stock?.[$('stockProduct').value]??null;stockInitial=formSnapshot($('stockForm'))};
$('stockForm').onsubmit=e=>{e.preventDefault();guard(async()=>{const request={kind:'adjust',productId:$('stockProduct').value,expected:stockExpected,mode:$('stockMode').value,quantity:$('stockQty').value,reason:$('stockReason').value};if(!confirm('確認此筆庫存調整？將保留異動紀錄。'))return;if(adjustPending&&!C.equalLegacy(adjustPending,request))throw Error('前次調整尚未確認，請以原內容重試並核對庫存');adjustPending=request;adjustOperation||=operationId();await writeInventory(request,adjustOperation);adjustPending=null;adjustOperation=null;$('stockQty').value='';$('stockReason').value='';stockExpected=management.inventory?.stock?.[$('stockProduct').value]??null;stockInitial=formSnapshot($('stockForm'));inventoryNavigate('home',true);$('inventoryNotice').textContent='庫存調整已儲存'})};
$('panel-inventory').querySelectorAll('[data-inv-go]').forEach(b=>b.onclick=()=>inventoryNavigate(b.dataset.invGo));
function productionPeriod(kind){const today=localDate();$('productionMonth').value=today.slice(0,7);$('productionStart').value=kind==='day'?today:today.slice(0,7)+'-01';$('productionEnd').value=kind==='day'?today:localDate(new Date(+today.slice(0,4),+today.slice(5,7),0,12));renderProductionStats()}
$('panel-inventory').querySelectorAll('[data-stat-period]').forEach(b=>b.onclick=()=>productionPeriod(b.dataset.statPeriod));for(const id of ['productionStart','productionEnd'])$(id).onchange=renderProductionStats;
$('productionMonth').onchange=()=>{const m=$('productionMonth').value;if(!/^\d{4}-\d{2}$/.test(m))return;$('productionStart').value=m+'-01';$('productionEnd').value=localDate(new Date(+m.slice(0,4),+m.slice(5,7),0,12));renderProductionStats()};
$('productionCsv').onclick=()=>{const start=$('productionStart').value,end=$('productionEnd').value;if(!C.validDate(start)||!C.validDate(end)||start>end){fail(Error('請選擇有效製作日期'));return}const stats=C.inventoryStats(management.inventory,start,end);downloadCsv([['製作統計（不含期初、其他入庫及退貨）',start,end],['製作日期','商品','包數'],...Object.entries(stats.daily).sort(([a],[b])=>a.localeCompare(b)).flatMap(([date,p])=>Object.entries(p).map(([pid,n])=>[date,stats.products.find(x=>x.productId===pid)?.name||pid,n])),['累計商品','包數'],...stats.products.map(p=>[p.name,p.quantity])],'製作統計-'+start)};
productionPeriod('month');

