function financeMoney(n){return 'NT$ '+Number(n||0).toLocaleString('zh-TW',{minimumFractionDigits:2,maximumFractionDigits:2})}
function downloadCsv(rows,name){const url=URL.createObjectURL(new Blob([C.csvText(rows)],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
let financeDraft=null,shrimpDraft=null,categorySignature='',categoryEdit=null,categoryPending=null;
const categoryExpected=new Map();
function financeState(){return management.finance||{}}
function categoryMap(){return {...Object.fromEntries(categories.map((name,i)=>['default'+i,{name,status:'active'}])),...(management.expenseCategories||{}),...(financeState().categories||{})}}
async function writeFinance(command){
 const serial=sessionSerial;let problem;
 if(command.kind==='legacy'){
  return transact(s=>{if(!C.equalLegacy(s?.expenses?.[command.id],command.legacySnapshot))throw Error('舊支出已被其他版本修改，請重新開啟');return {...s,finance:C.applyFinance(s.finance,command,op,firebase.database.ServerValue.TIMESTAMP)}});
 }
 const result=await rootRef().child('finance').transaction(f=>{problem=null;try{return C.applyFinance(f,command,op,firebase.database.ServerValue.TIMESTAMP)}catch(e){problem=e;return}},undefined,false);
 if(serial!==sessionSerial)throw Error('登入狀態已變更，請回原帳號確認結果');if(!result.committed)throw problem||Error('財務交易未完成，請重新同步後重試');return result;
}
$('panel-reports').innerHTML=`<h2>營業報表</h2><p class="management-help">取消／退貨不自動退款或扣減原訂單金額。以下已出貨包數依原出貨狀態，含後續退貨；未出貨包數為原訂單分類，實際待出貨需求請看庫存首頁。製作數量請至庫存製作統計查看，不列營收。</p><div class="row"><select id="reportPreset"><option value="day">每日</option><option value="week">本週</option><option value="month" selected>本月</option><option value="year">全年</option><option value="custom">自訂</option></select><input id="reportStart" type="date" aria-label="開始日期"><input id="reportEnd" type="date" aria-label="結束日期"><button id="exportReport">匯出 CSV</button></div><p class="management-help">台灣日期、含首尾。A 商品訂單依建立日；B 商品實收依收款日；C 採購及營運支出依採購日（不論付款）；D 實付支出依付款日（包含以前月份採購）；E 自養蝦估算依製作日。客人配送運費不列商品收入或支出。材料採購與耗用日期可能不同，估算不代表精確會計淨利；自養蝦成本不是現金付款。</p><div id="reportStats" class="management-grid"></div><p id="unknownPayments" role="status"></p><div id="reportProducts"></div>`;
function preset(){const now=localDate(),p=$('reportPreset').value;let start=now,end=now;if(p==='month'){start=now.slice(0,8)+'01';const [y,m]=now.split('-').map(Number);end=localDate(new Date(Date.UTC(y,m,0,4)))}if(p==='year'){start=now.slice(0,4)+'-01-01';end=now.slice(0,4)+'-12-31'}if(p==='week'){const d=new Date(now+'T00:00:00+08:00'),day=new Date(d.getTime()+8*3600000).getUTCDay();start=localDate(d.getTime()-((day+6)%7)*86400000)}if(p!=='custom'){$('reportStart').value=start;$('reportEnd').value=end}renderReports()}
function reportRows(r){return [['訂單數（商品金額可核對）',r.count],['銷售數量（含贈品，包／組）',r.packs],['A 商品訂單金額（建立日）',r.A],['B 商品實收（收款日）',r.B],['所選訂單未付款商品金額',r.unpaid],['所選訂單目前已付款商品金額',r.paid],['已出貨銷售數量（含贈品，包／組）',r.shipped],['未出貨銷售數量（含贈品，包／組）',r.unshipped],['C 採購及營運支出（採購日）',r.C],['當期採購目前已付款',r.purchasePaid],['當期採購目前未付款',r.purchaseUnpaid],['當期採購付款狀態不明',r.purchaseUnknown],['D 實付採購及營運支出（付款日）',r.D],['E 自養蝦估算成本（非現金／製作日）',r.E],['外購蝦製作成本（僅供查看，不再扣除）',r.externalShrimp],['簡易估算利潤 A−C−E（非精確淨利）',r.estimated],['收款基礎估算比較值 B−D−E（非現金餘額）',r.comparison],['商品現金收支差額 B−D',r.cashBalance],['全期收款日期不明筆數',r.unknownCount],['全期收款日期不明商品金額',r.unknownAmount],['全期商品金額待核對筆數',r.unresolvedOrders],['全期待核對訂單原總額（非商品收入）',r.unresolvedOrderAmount],['全期建立日期不明筆數',r.unknownCreated],['全期支出已付但付款日期不明筆數',r.unknownExpensePayments],['全期支出已付但付款日期不明金額',r.unknownExpensePaymentAmount],['支出日期／金額／覆層衝突待核對筆數',r.invalidExpenses]]}
function renderReports(){if(!$('reportStart').value)return;try{reportData=C.financeReport(orders,management.expenses||{},financeState(),$('reportStart').value,$('reportEnd').value);const r=reportData;renderUncollectedReport();$('reportStats').innerHTML=reportRows(r).slice(0,18).map(([k,v],i)=>'<div class="card">'+esc(k)+'<h3>'+(i===0||i===1||i===6||i===7?v:financeMoney(v))+'</h3></div>').join('');$('unknownPayments').textContent=`全期收款日期不明：${r.unknownCount} 筆／${financeMoney(r.unknownAmount)}，不計本期 B。商品金額待核對 ${r.unresolvedOrders} 筆（原總額 ${financeMoney(r.unresolvedOrderAmount)}，不計 A/B）；建立日期不明 ${r.unknownCreated} 筆；支出待核對 ${r.invalidExpenses} 筆；已付支出付款日期不明 ${r.unknownExpensePayments} 筆／${financeMoney(r.unknownExpensePaymentAmount)}。付款狀態不明的舊支出不計 D。`;$('reportProducts').innerHTML='<h3>商品銷售排行（依建立日）</h3><table><tr><th>商品</th><th>付費數量（包／組）</th><th>贈品</th><th>商品金額</th></tr>'+r.sales.map(x=>'<tr><td>'+esc(x.name)+'</td><td>'+x.qty+'</td><td>'+x.gift+'</td><td>'+financeMoney(x.revenue)+'</td></tr>').join('')+'</table>'}catch(e){reportData=null;$('reportStats').textContent='請輸入有效日期區間：'+e.message;$('unknownPayments').textContent='';$('reportProducts').textContent=''}}
$('reportPreset').onchange=preset;for(const id of ['reportStart','reportEnd'])$(id).onchange=()=>{$('reportPreset').value='custom';renderReports()};
$('exportReport').onclick=()=>{if(reportData)downloadCsv([['快樂蝦農營業報表',$('reportStart').value,$('reportEnd').value],['口徑','A建立日；B收款日；C採購日；D付款日；E製作日／非現金；估算非會計淨利'],...reportRows(reportData),...uncollectedReportRows(),['商品','付費數量（包／組）','贈品數量（包／組）','商品金額'],...reportData.sales.map(x=>[x.name,x.qty,x.gift,x.revenue])],'快樂蝦農報表-'+$('reportStart').value)};
$('panel-expenses').innerHTML=`<h2>料理包支出管理</h2><p class="management-help">不記養殖支出、不扣材料／成品庫存；客人配送運費不記支出。舊支出只讀，編輯／作廢儲存在獨立覆層，每筆僅統計一次。</p><form id="expenseForm" class="card"><h3>採購／營運記帳</h3><input id="expenseId" type="hidden"><label>模式<select id="expenseMode"><option value="simple">簡單記帳</option><option value="detailed">詳細記帳</option></select></label><label>採購／支出日期<input id="expenseDate" type="date" required></label><div id="expenseSimple"><label>項目<input id="expenseTitle"></label><label>分類<select id="expenseCategory"></select></label><label>金額<input id="expenseAmount" inputmode="decimal" placeholder="0.00"></label><label><input id="simpleShrimp" type="checkbox">外購蝦品項</label><label>外購蝦總台斤數（外購蝦必填）<input id="simpleWeight" inputmode="decimal"></label></div><div id="expenseDetailed" class="hidden"><div id="purchaseLines"></div><button type="button" id="addPurchaseLine">新增品項</button></div><label>自己負擔的採購運費<input id="expenseShipping" inputmode="decimal" value="0"></label><label>付款狀態<select id="expensePayment"><option value="" disabled>請確認付款狀態</option><option value="unpaid">未付款</option><option value="paid">全額已付款</option></select></label><label id="expensePaidDateBox">實際付款日期<input id="expensePaidDate" type="date"></label><label>商家<input id="expenseMerchant"></label><label>備註<textarea id="expenseNotes"></textarea></label><p id="expenseTotal" role="status"></p><button class="primary">儲存支出</button><button type="button" id="cancelExpense">取消／新增另一筆</button></form><div class="card"><h3>料理包分類設定</h3><select id="categorySelect"></select><input id="categoryName" placeholder="分類名稱"><button id="addCategory">新增分類</button><button id="renameCategory">修改所選分類</button><button id="toggleCategory">停用／恢復分類</button></div><div class="row"><input id="expenseSearch" placeholder="搜尋項目、分類、商家、備註、操作人員"><input id="expenseStart" type="date" aria-label="支出開始日期"><input id="expenseEnd" type="date" aria-label="支出結束日期"><select id="expenseFilter"><option value="">全部付款狀態</option><option value="paid">已付款</option><option value="unpaid">未付款</option><option value="unknown">付款不明</option></select><label><input id="showVoidExpenses" type="checkbox">顯示作廢</label><button id="exportExpenses">匯出支出 CSV</button></div><div id="expenseList"></div><form id="shrimpForm" class="card"><h3>蝦子製作成本（不連動庫存）</h3><input id="shrimpId" type="hidden"><label>製作日期<input id="shrimpDate" type="date" required></label><label>料理包品項<select id="shrimpProduct" required></select></label><label>來源<select id="shrimpSource"><option value="own">自養蝦（非現金估算）</option><option value="purchased">外購蝦（關聯採購，不再次扣成本）</option></select></label><label>使用台斤數（1 台斤＝600 公克）<input id="shrimpWeight" inputmode="decimal" required></label><label id="shrimpPriceBox">每台斤成本<input id="shrimpPrice" inputmode="decimal"></label><label id="shrimpLinkBox">原蝦子採購品項<select id="shrimpLink"></select></label><label>製作包數（選填）<input id="shrimpPacks" inputmode="numeric"></label><label>備註<textarea id="shrimpNotes"></textarea></label><p id="shrimpTotal" role="status"></p><button class="primary">儲存製作成本</button><button type="button" id="cancelShrimp">取消／新增另一筆</button></form><div class="row"><input id="shrimpSearch" placeholder="搜尋商品、來源、備註"><input id="shrimpStart" type="date" aria-label="製作開始日期"><input id="shrimpEnd" type="date" aria-label="製作結束日期"><label><input id="showVoidShrimp" type="checkbox">顯示作廢</label><button id="exportShrimp">匯出成本 CSV</button></div><div id="shrimpList"></div><h3>財務操作紀錄</h3><div id="financeOperations"></div>`;
function categoryOptions(selected=''){return Object.entries(categoryMap()).filter(([id,c])=>c.status!=='void'||id===selected).map(([id,c])=>'<option value="'+esc(id)+'"'+(id===selected?' selected':'')+'>'+esc(c.name)+(c.status==='void'?'（停用）':'')+'</option>').join('')}
function addPurchaseLine(line={},id=operationId()){const div=document.createElement('div');div.className='purchase-line card';div.dataset.line=id;div.innerHTML='<label>品項<input data-field="name" value="'+esc(line.name||'')+'"></label><label>分類<select data-field="categoryId">'+categoryOptions(line.categoryId)+'</select></label><div class="finance-line-grid"><label>數量<input data-field="quantity" inputmode="decimal" value="'+esc(line.quantityMilli==null?'1':line.quantityMilli/1000)+'"></label><label>單位<input data-field="unit" value="'+esc(line.unit||'')+'"></label><label>單價<input data-field="unitPrice" inputmode="decimal" value="'+esc(line.unitPriceCents==null?'':(line.unitPriceCents/100).toFixed(2))+'"></label></div><label><input data-field="shrimp" type="checkbox" '+(line.shrimp?'checked':'')+'>外購蝦</label><label>外購蝦總台斤數<input data-field="weightCatty" inputmode="decimal" value="'+esc(line.weightMilliCatty?line.weightMilliCatty/1000:'')+'"></label><p data-line-total></p><button type="button" data-remove-line>移除此品項</button>';div.querySelector('[data-remove-line]').onclick=()=>{if(!busy){div.remove();previewExpense()}};$('purchaseLines').append(div)}
function resetExpense(){if(!$('expenseForm'))return;$('expenseForm').reset();$('expenseId').value='';$('expenseDate').value=localDate();$('expensePayment').value='unpaid';$('purchaseLines').textContent='';financeDraft={id:operationId(),operation:operationId(),expected:null,kind:'purchase',completed:false,lineId:'simple'};addPurchaseLine({},'line1');expenseMode();paymentFields()}
function expenseMode(){$('expenseSimple').classList.toggle('hidden',$('expenseMode').value!=='simple');$('expenseDetailed').classList.toggle('hidden',$('expenseMode').value!=='detailed');previewExpense()}
$('expenseMode').onchange=()=>{if($('expenseMode').value==='simple'&&$('purchaseLines').children.length>1&&!confirm('簡單模式只儲存單項金額，不保留本次多品項明細。確認切換？')){$('expenseMode').value='detailed';return}expenseMode()};
function paymentFields(){$('expensePaidDateBox').classList.toggle('hidden',$('expensePayment').value!=='paid');$('expensePaidDate').required=$('expensePayment').value==='paid';previewExpense()}
$('expensePayment').onchange=paymentFields;$('addPurchaseLine').onclick=()=>addPurchaseLine();$('cancelExpense').onclick=()=>{if(!busy)resetExpense()};
function purchaseDraftData(){const mode=$('expenseMode').value,items={};if(mode==='simple')items[financeDraft.lineId]={name:$('expenseTitle').value,categoryId:$('expenseCategory').value,quantity:'1',unit:'筆',unitPrice:$('expenseAmount').value,shrimp:$('simpleShrimp').checked,weightCatty:$('simpleWeight').value};else for(const row of $('purchaseLines').children){const line={};row.querySelectorAll('[data-field]').forEach(x=>line[x.dataset.field]=x.type==='checkbox'?x.checked:x.value);items[row.dataset.line]=line;}return {mode,purchaseDate:$('expenseDate').value,items,shipping:$('expenseShipping').value,paymentStatus:$('expensePayment').value,paidDate:$('expensePaidDate').value,merchant:$('expenseMerchant').value,notes:$('expenseNotes').value}}
function previewExpense(){try{const p=C.financePurchase(purchaseDraftData());$('expenseTotal').textContent='品項 '+financeMoney(p.subtotalCents/100)+' ＋ 自付運費 '+financeMoney(p.shippingCents/100)+' ＝ '+financeMoney(p.totalCents/100)}catch(e){$('expenseTotal').textContent='待完成：'+e.message}for(const row of $('purchaseLines').children){try{const q=row.querySelector('[data-field="quantity"]').value,p=row.querySelector('[data-field="unitPrice"]').value;row.querySelector('[data-line-total]').textContent='小計 '+financeMoney(C.roundedProduct(C.scaled(q,3),C.scaled(p,2))/100)}catch(_){row.querySelector('[data-line-total]').textContent='小計待填'}}}
$('expenseForm').addEventListener('input',previewExpense);
$('expenseForm').onsubmit=e=>{e.preventDefault();if(financeDraft?.completed){fail(Error('此表單已儲存；請從清單編輯，或按取消／新增另一筆'));return}guard(async()=>{const draft=financeDraft;if(!draft)throw Error('請重新開啟記帳表單');const data=purchaseDraftData();C.financePurchase(data);await writeFinance({...draft,data,legacySnapshot:draft.legacySnapshot});draft.completed=true;financeSaved('purchase');$('expenseTotal').textContent='已儲存；再次記帳請按「取消／新增另一筆」，避免重複提交。'})};
function editExpense(entry){if(busy)return;if(entry.source==='legacy'&&!management.expenses?.[entry.sourceId]){fail(Error('原舊支出已由其他版本移除，請先人工核對；本系統不重建或搬移原資料'));return}if(entry.source==='legacy'&&financeState().legacyExpenseOverrides?.[entry.sourceId]&&!C.equalLegacy(management.expenses[entry.sourceId],financeState().legacyExpenseOverrides[entry.sourceId].legacySnapshot)){fail(Error('原舊支出已被其他版本修改，覆層暫停統計；請先人工核對原紀錄與操作歷史'));return}resetExpense();const isLegacy=entry.source==='legacy',old=isLegacy?financeState().legacyExpenseOverrides?.[entry.sourceId]||null:financeState().purchases?.[entry.sourceId]||null,p=entry;
 financeDraft={id:entry.sourceId,operation:operationId(),expected:old?JSON.parse(JSON.stringify(old)):null,kind:isLegacy?'legacy':'purchase',legacySnapshot:isLegacy?JSON.parse(JSON.stringify(management.expenses[entry.sourceId])):undefined,completed:false,lineId:Object.keys(p.items||{})[0]||'simple'};$('expenseId').value=entry.id;$('expenseDate').value=p.purchaseDate||'';$('expenseMode').value=p.mode||'simple';const line=Object.values(p.items||{})[0]||{};$('expenseTitle').value=line.name||p.title||'';$('expenseCategory').innerHTML=categoryOptions(line.categoryId);$('expenseCategory').value=line.categoryId||'default0';$('expenseAmount').value=(p.subtotalCents??p.totalCents??0)/100;$('simpleShrimp').checked=!!line.shrimp;$('simpleWeight').value=line.weightMilliCatty?line.weightMilliCatty/1000:'';$('purchaseLines').textContent='';for(const [id,l] of Object.entries(p.items||{}))addPurchaseLine(l,id);$('expenseShipping').value=(p.shippingCents||0)/100;$('expensePayment').value=p.payment?.status==='paid'?'paid':p.payment?.status==='unpaid'?'unpaid':'';$('expensePaidDate').value=p.payment?.paidDate||'';$('expenseMerchant').value=p.merchant||'';$('expenseNotes').value=p.notes||'';expenseMode();paymentFields();if(p.payment?.status==='unknown')$('expenseTotal').textContent='舊支出付款狀態不明，儲存前請人工確認未付／全付；不會自動判定。';$('expenseForm').scrollIntoView({block:'start'});return true}
function visibleExpenses(){const q=$('expenseSearch').value.toLowerCase(),start=$('expenseStart').value,end=$('expenseEnd').value,pay=$('expenseFilter').value;return C.financeEntries(management.expenses||{},financeState()).filter(p=>(p.status!=='void'||$('showVoidExpenses').checked)&&(!start||p.purchaseDate>=start)&&(!end||p.purchaseDate<=end)&&(!pay||p.payment?.status===pay)&&[p.merchant,p.notes,p.operator,...Object.values(p.items||{}).flatMap(l=>[l.name,categoryMap()[l.categoryId]?.name,l.category])].join(' ').toLowerCase().includes(q)).sort((a,b)=>String(b.purchaseDate).localeCompare(String(a.purchaseDate)))}
async function setFinanceStatus(kind,id,old,status,legacySnapshot){if(!confirm(status==='void'?'確認作廢？原資料與歷史保留，報表排除此筆。':'確認復原？將重新納入統計。'))return;await guard(()=>writeFinance({kind,id,expected:old,action:'status',status,operation:operationId(),legacySnapshot}))}
function renderExpenses(){const cats=categoryMap(),signature=JSON.stringify(cats);if(signature!==categorySignature){categorySignature=signature;for(const id of ['expenseCategory','categorySelect']){const v=$(id).value;$(id).innerHTML=categoryOptions(v,id==='categorySelect');if(cats[v])$(id).value=v}categoryExpected.clear();for(const [id] of Object.entries(cats))categoryExpected.set(id,financeState().categories?.[id]?JSON.parse(JSON.stringify(financeState().categories[id])):null);for(const row of $('purchaseLines').children){const select=row.querySelector('[data-field="categoryId"]'),v=select.value;select.innerHTML=categoryOptions(v)}}
 const entries=visibleExpenses();$('expenseList').innerHTML=entries.map((p,n)=>'<article class="card"><b>'+esc(Object.values(p.items||{}).map(l=>l.name).join('、'))+' · '+(p.totalCents===null?'金額待核對':financeMoney(p.totalCents/100))+'</b><p>'+esc(p.purchaseDate||'日期不明')+' · '+(p.source==='legacy'?'舊支出（原資料只讀）':'新版記帳')+' · '+esc(({paid:'已付款',unpaid:'未付款',unknown:'付款狀態不明'})[p.payment?.status]||'付款不明')+' '+esc(p.payment?.paidDate||'')+'<br>'+esc(p.merchant||'')+' · '+esc(p.operator||'')+'<br>'+esc(p.notes||'')+(p.status==='void'?'<br>已作廢':'')+'</p><button data-expense="'+n+'">編輯'+(p.source==='legacy'?'覆層':'')+'</button><button data-delexpense="'+n+'">'+(p.status==='void'?'復原':'作廢')+'</button></article>').join('')||'<p>沒有符合的支出</p>';
 $('expenseList').querySelectorAll('[data-expense]').forEach(b=>b.onclick=()=>editExpense(entries[+b.dataset.expense]));$('expenseList').querySelectorAll('[data-delexpense]').forEach(b=>b.onclick=()=>{const p=entries[+b.dataset.delexpense],kind=p.source==='legacy'?'legacy':'purchase',old=kind==='legacy'?financeState().legacyExpenseOverrides?.[p.sourceId]||null:financeState().purchases[p.sourceId];if(kind==='legacy'&&!old){fail(Error('舊支出請先編輯確認資料並儲存覆層，再作廢；原支出保持唯讀。'));return}setFinanceStatus(kind,p.sourceId,old,p.status==='void'?'active':'void',p.source==='legacy'?management.expenses[p.sourceId]:undefined)});renderShrimp();renderFinanceOperations()}
for(const id of ['expenseSearch','expenseStart','expenseEnd','expenseFilter','showVoidExpenses'])$(id).oninput=renderExpenses;
$('exportExpenses').onclick=()=>downloadCsv([['支出日期','來源 ID','品項','分類','數量','單位','單價','品項金額','計算小計','金額來源','差異確認','品項備註','自付運費（每採購首列）','採購總額（首列）','付款狀態','付款日期','商家','備註','狀態'],...visibleExpenses().flatMap(p=>Object.values(p.items||{}).map((l,i)=>[p.purchaseDate,p.id,l.name,categoryMap()[l.categoryId]?.name||l.category,l.quantityMilli==null?'':l.quantityMilli/1000,l.unit,l.unitPriceCents==null?'':l.unitPriceCents/100,l.subtotalCents==null?'待核對':l.subtotalCents/100,l.calculatedSubtotalCents==null?'':l.calculatedSubtotalCents/100,l.amountBasis||'歷史金額',l.differenceConfirmedFor?'已確認':'',l.notes||'',i?'':p.shippingCents/100,i?'':p.totalCents==null?'待核對':p.totalCents/100,p.payment?.status,p.payment?.paidDate,p.merchant,p.notes,p.status]))],'快樂蝦農料理包支出');
$('categoryName').addEventListener('input',()=>{const id=$('categorySelect').value;if(categoryEdit?.id!==id)categoryEdit={id,expected:categoryExpected.get(id)||null}});
$('categorySelect').onchange=()=>{const id=$('categorySelect').value;categoryEdit={id,expected:categoryExpected.get(id)||null}};
async function saveCategory(add=false,toggle=false){const id=add?(categoryPending?.id||operationId()):$('categorySelect').value,expected=add?null:categoryEdit?.id===id?categoryEdit.expected:categoryExpected.get(id)||null,name=toggle?categoryMap()[id]?.name:$('categoryName').value.trim();const data={name,status:toggle&&categoryMap()[id]?.status!=='void'?'void':'active'};if(add){if(categoryPending&&!C.equalLegacy(categoryPending.data,data)){fail(Error('上次新增分類尚未確認，請先用原名稱重試並確認清單'));return}categoryPending||={id,operation:operationId(),data};}await guard(async()=>{await writeFinance({kind:'category',id,expected,operation:add?categoryPending.operation:operationId(),data});$('categoryName').value='';categoryEdit=null;categoryPending=null})}
$('addCategory').onclick=()=>saveCategory(true);$('renameCategory').onclick=()=>saveCategory();$('toggleCategory').onclick=()=>saveCategory(false,true);
function resetShrimp(){if(!$('shrimpForm'))return;$('shrimpForm').reset();$('shrimpId').value='';$('shrimpDate').value=localDate();shrimpDraft={id:operationId(),operation:operationId(),expected:null,kind:'shrimp',completed:false};shrimpFields()}
function shrimpFields(){$('shrimpPriceBox').classList.toggle('hidden',$('shrimpSource').value!=='own');$('shrimpLinkBox').classList.toggle('hidden',$('shrimpSource').value!=='purchased');previewShrimp()}
function shrimpData(){const link=$('shrimpLink').value.split('/'),productId=$('shrimpProduct').value;return {date:$('shrimpDate').value,productId,productName:salesProducts()[productId]?.name||shrimpDraft?.expected?.productName||'',sourceType:$('shrimpSource').value,weightCatty:$('shrimpWeight').value,unitCost:$('shrimpPrice').value,purchaseId:link[0],lineId:link[1],packs:$('shrimpPacks').value,notes:$('shrimpNotes').value}}
function previewShrimp(){try{const s=C.financeShrimp(shrimpData(),financeState());$('shrimpTotal').textContent=financeMoney(s.estimatedCostCents/100)+(s.sourceType==='own'?'（非現金估算）':'（已含採購，不再次扣除）')}catch(e){$('shrimpTotal').textContent='待完成：'+e.message}}
$('shrimpSource').onchange=shrimpFields;$('shrimpForm').addEventListener('input',previewShrimp);$('cancelShrimp').onclick=()=>{if(!busy)resetShrimp()};
$('shrimpForm').onsubmit=e=>{e.preventDefault();if(shrimpDraft?.completed){fail(Error('此表單已儲存；請從清單編輯，或按取消／新增另一筆'));return}guard(async()=>{const draft=shrimpDraft;await writeFinance({...draft,data:shrimpData()});draft.completed=true;financeSaved('shrimp');$('shrimpTotal').textContent='已儲存；新增下一筆請按「取消／新增另一筆」。'})};
function visibleShrimp(){const q=$('shrimpSearch').value.toLowerCase();return Object.entries(financeState().shrimpCosts||{}).filter(([,s])=>(s.status!=='void'||$('showVoidShrimp').checked)&&(!$('shrimpStart').value||s.date>=$('shrimpStart').value)&&(!$('shrimpEnd').value||s.date<=$('shrimpEnd').value)&&[s.productName,s.notes,s.sourceType==='own'?'自養蝦':'外購蝦'].join(' ').toLowerCase().includes(q)).sort((a,b)=>b[1].date.localeCompare(a[1].date))}
function renderShrimp(){const product=$('shrimpProduct').value,productsAll=salesProducts();if(shrimpDraft?.expected&&!productsAll[shrimpDraft.expected.productId])productsAll[shrimpDraft.expected.productId]={name:shrimpDraft.expected.productName};$('shrimpProduct').innerHTML=Object.entries(productsAll).map(([id,p])=>'<option value="'+esc(id)+'">'+esc(p.name)+'</option>').join('');if(productsAll[product])$('shrimpProduct').value=product;const link=$('shrimpLink').value;$('shrimpLink').innerHTML='<option value="">請選擇原蝦子採購</option>'+Object.entries(financeState().purchases||{}).filter(([,p])=>p.status==='active').flatMap(([id,p])=>Object.entries(p.items).filter(([,l])=>l.shrimp).map(([lid,l])=>'<option value="'+esc(id+'/'+lid)+'">'+esc(p.purchaseDate+' '+l.name)+' · '+l.weightMilliCatty/1000+' 台斤</option>')).join('');$('shrimpLink').value=link;
 const list=visibleShrimp();$('shrimpList').innerHTML=list.map(([id,s],n)=>'<article class="card"><b>'+esc(s.productName)+' · '+financeMoney(s.estimatedCostCents/100)+'</b><p>'+esc(s.date)+' · '+(s.sourceType==='own'?'自養蝦／非現金':'外購蝦／不重扣')+' · '+s.weightMilliCatty/1000+' 台斤 · '+esc(s.notes||'')+(s.status==='void'?' · 已作廢':'')+'</p><button data-shrimp-edit="'+n+'">編輯</button><button data-shrimp-status="'+n+'">'+(s.status==='void'?'復原':'作廢')+'</button></article>').join('')||'<p>尚無符合的製作成本</p>';
 $('shrimpList').querySelectorAll('[data-shrimp-edit]').forEach(b=>b.onclick=()=>{if(busy)return;const [id,s]=list[+b.dataset.shrimpEdit];shrimpDraft={id,operation:operationId(),kind:'shrimp',expected:JSON.parse(JSON.stringify(s)),completed:false};$('shrimpId').value=id;$('shrimpDate').value=s.date;$('shrimpProduct').value=s.productId;$('shrimpSource').value=s.sourceType;$('shrimpWeight').value=s.weightMilliCatty/1000;$('shrimpPrice').value=s.unitCostCents/100;$('shrimpLink').value=s.purchaseId+'/'+s.lineId;$('shrimpPacks').value=s.packs||'';$('shrimpNotes').value=s.notes||'';shrimpFields();openShrimpEditor();$('shrimpForm').scrollIntoView({block:'start'})});$('shrimpList').querySelectorAll('[data-shrimp-status]').forEach(b=>b.onclick=()=>{const [id,s]=list[+b.dataset.shrimpStatus];setFinanceStatus('shrimp',id,s,s.status==='void'?'active':'void')})}
for(const id of ['shrimpSearch','shrimpStart','shrimpEnd','showVoidShrimp'])$(id).oninput=renderShrimp;
$('exportShrimp').onclick=()=>downloadCsv([['製作日期','商品','來源','台斤（600g）','每台斤成本','估算成本','製作包數','採購 ID','採購品項 ID','備註','狀態'],...visibleShrimp().map(([id,s])=>[s.date,s.productName,s.sourceType,s.weightMilliCatty/1000,s.unitCostCents/100,s.estimatedCostCents/100,s.packs||'',s.purchaseId,s.lineId,s.notes,s.status])],'快樂蝦農蝦子製作成本');
function renderFinanceOperations(){$('financeOperations').innerHTML=Object.values(financeState().operations||{}).sort((a,b)=>(+b.date||0)-(+a.date||0)).slice(0,100).map(h=>'<article class="card">'+esc(dateText(h.date))+' · '+esc(h.operator)+' · '+esc(({purchase:'採購',shrimp:'蝦子成本',category:'分類',legacy:'舊支出覆層'})[h.kind]||h.kind)+' · '+esc(h.id)+' · '+esc(h.action)+'<details><summary>修訂前後資料</summary><pre>'+esc(JSON.stringify({before:h.before,after:h.after},null,2))+'</pre></details></article>').join('')||'<p>尚無財務操作</p>'}
resetExpense();resetShrimp();preset();

// Integrated into management.js locally; not a runtime dependency.
function categoryOptions(selected='',includeInactive=false){return Object.entries(categoryMap()).filter(([id,c])=>includeInactive||c.status!=='void'||id===selected).map(([id,c])=>'<option value="'+esc(id)+'"'+(id===selected?' selected':'')+'>'+esc(c.name)+(c.status==='void'?'（停用）':'')+'</option>').join('')}
function addPurchaseLine(line={},id=operationId()){
 const div=document.createElement('div');div.className='purchase-line card';div.dataset.line=id;
 div.dataset.amountManual=line.amountBasis==='manual'?'true':'false';div.dataset.confirmFor=line.differenceConfirmedFor||'';
 const value=(n,scale)=>n==null?'':String(n/scale);
 div.innerHTML='<label>品名<span class="required-mark">必填</span><input data-field="name" value="'+esc(line.name||'')+'"></label><label>分類<span class="required-mark">必填</span><select data-field="categoryId">'+categoryOptions(line.categoryId)+'</select></label><label>品項金額<span class="required-mark">必填</span><input data-field="amount" inputmode="decimal" value="'+esc(value(line.subtotalCents,100))+'" placeholder="0.00"></label><details class="line-options"><summary>數量、單價與其他資料（選填）</summary><div class="finance-line-grid"><label>數量<input data-field="quantity" inputmode="decimal" value="'+esc(value(line.quantityMilli,1000))+'"></label><label>單位<input data-field="unit" value="'+esc(line.unit||'')+'"></label><label>單價<input data-field="unitPrice" inputmode="decimal" value="'+esc(value(line.unitPriceCents,100))+'"></label></div><label>品項備註<input data-field="notes" value="'+esc(line.notes||'')+'"></label><label><input data-field="shrimp" type="checkbox" '+(line.shrimp?'checked':'')+'>外購蝦品項</label><label>外購蝦總台斤數<input data-field="weightCatty" inputmode="decimal" value="'+esc(line.weightMilliCatty?line.weightMilliCatty/1000:'')+'"></label></details><p data-line-total role="status"></p><label data-difference-box class="amount-warning hidden"><input data-confirm-difference type="checkbox" '+(line.differenceConfirmedFor?'checked':'')+'>我已確認保留手動金額（與計算小計不同）</label><button type="button" data-remove-line>移除此品項</button>';
 div.addEventListener('input',e=>{
  const field=e.target.dataset.field;if(['quantity','unitPrice','amount'].includes(field)){div.dataset.confirmFor='';div.querySelector('[data-confirm-difference]').checked=false;if(field==='amount')div.dataset.amountManual='true';
   if(field!=='amount'&&div.dataset.amountManual!=='true'){try{const q=div.querySelector('[data-field="quantity"]').value,p=div.querySelector('[data-field="unitPrice"]').value;if(q&&p)div.querySelector('[data-field="amount"]').value=(C.roundedProduct(C.scaled(q,3),C.scaled(p,2))/100).toFixed(2)}catch(_){}}
  }
  if(e.target.matches('[data-confirm-difference]')){try{div.dataset.confirmFor=e.target.checked?lineConfirmation(div):''}catch(_){div.dataset.confirmFor=''}}
 });
 div.querySelector('[data-remove-line]').onclick=()=>{if(!busy){div.remove();previewExpense()}};$('purchaseLines').append(div);
}
function lineConfirmation(row){return [C.scaled(row.querySelector('[data-field="quantity"]').value,3),C.scaled(row.querySelector('[data-field="unitPrice"]').value,2),C.scaled(row.querySelector('[data-field="amount"]').value,2)].join('|')}
function purchaseDraftData(){
 const mode=$('expenseMode').value,items={};if(mode==='simple')items[financeDraft.lineId]={name:$('expenseTitle').value,categoryId:$('expenseCategory').value,amount:$('expenseAmount').value,shrimp:$('simpleShrimp').checked,weightCatty:$('simpleWeight').value,amountBasis:'manual'};
 else for(const row of $('purchaseLines').children){const line={};row.querySelectorAll('[data-field]').forEach(x=>line[x.dataset.field]=x.type==='checkbox'?x.checked:x.value);line.amountBasis=row.dataset.amountManual==='true'?'manual':'calculated';line.differenceConfirmedFor=row.querySelector('[data-confirm-difference]').checked?row.dataset.confirmFor:'';items[row.dataset.line]=line;}
 return {schemaVersion:2,mode,purchaseDate:$('expenseDate').value,items,shipping:$('expenseShipping').value,paymentStatus:$('expensePayment').value,paidDate:$('expensePaidDate').value,merchant:$('expenseMerchant').value,notes:$('expenseNotes').value};
}
function previewExpense(){
 for(const row of $('purchaseLines').children){let differs=false;try{const q=row.querySelector('[data-field="quantity"]').value,p=row.querySelector('[data-field="unitPrice"]').value,amount=row.querySelector('[data-field="amount"]').value;if(q&&p){const calculated=C.roundedProduct(C.scaled(q,3),C.scaled(p,2));row.querySelector('[data-line-total]').textContent='數量 × 單價 ＝ '+financeMoney(calculated/100);differs=!!amount&&C.scaled(amount,2)!==calculated;}else row.querySelector('[data-line-total]').textContent='以品項金額記帳；數量、單價可留白';}catch(e){row.querySelector('[data-line-total]').textContent=e.message}row.querySelector('[data-difference-box]').classList.toggle('hidden',!differs);}
 try{const p=C.financePurchase(purchaseDraftData());$('expenseTotal').textContent='品項 '+financeMoney(p.subtotalCents/100)+' ＋ 自付運費 '+financeMoney(p.shippingCents/100)+' ＝ '+financeMoney(p.totalCents/100)}catch(e){$('expenseTotal').textContent='待完成：'+e.message}
}

// Views are ordinary sections inside orders.html, never dialogs or separate HTML files.
let financeView='home',purchaseBaseline='',shrimpBaseline='',financeRoute={page:'orders',view:'home',index:0},restoringFinanceHistory=false;
const financePanels={};
const expensePanel=$('panel-expenses'),purchaseForm=$('expenseForm'),costForm=$('shrimpForm');
const categoryCard=$('categorySelect').parentElement,expenseFilters=$('expenseSearch').parentElement,shrimpFilters=$('shrimpSearch').parentElement;
const expenseList=$('expenseList'),shrimpList=$('shrimpList'),operations=$('financeOperations'),expenseExport=$('exportExpenses'),shrimpExport=$('exportShrimp');
expenseExport.remove();shrimpExport.remove();
expensePanel.textContent='';
expensePanel.innerHTML='<div id="financeNotice" role="status" class="management-help"></div>';
for(const [id,title] of [['home','料理包支出'],['purchase','新增支出'],['shrimp','蝦子製作成本'],['records','支出紀錄'],['detail','支出明細'],['more','更多功能']]){
 const s=document.createElement('section');s.className='finance-view'+(id==='home'?'':' hidden');s.id='finance-'+id;
 s.innerHTML='<header class="finance-heading">'+(id==='home'?'':'<button type="button" data-finance-back aria-label="返回支出首頁">‹ 返回</button>')+'<h2>'+title+'</h2>'+(id==='home'?'<button type="button" data-finance-go="more">更多功能</button>':'')+'</header>';expensePanel.append(s);financePanels[id]=s;
}
financePanels.home.insertAdjacentHTML('beforeend','<label class="finance-month">統計月份<input id="expenseMonth" type="month" value="'+localDate().slice(0,7)+'"></label><div id="expenseHomeStats" class="finance-home-stats"></div><p id="expenseHomeWarnings" class="management-help"></p><div class="finance-actions"><button type="button" class="primary" id="financeNewExpense">＋ 新增支出</button><button type="button" data-finance-go="shrimp">蝦子成本</button><button type="button" data-finance-go="records">支出紀錄</button></div><h3>最近支出</h3><div id="recentExpenses"></div>');
financePanels.purchase.append(purchaseForm);purchaseForm.querySelector('h3').textContent='採購／營運記帳';
financePanels.shrimp.append(costForm,shrimpFilters,shrimpList);financePanels.shrimp.insertAdjacentHTML('beforeend','<p class="management-help">自養蝦估算不是付款，請勿另建同筆採購；外購蝦需關聯原採購，不再次扣成本。1 台斤＝600 公克。</p>');
financePanels.records.append(expenseFilters,expenseList);expenseFilters.insertAdjacentHTML('beforeend','<label>分類<select id="expenseCategoryFilter"><option value="">全部分類</option></select></label>');
financePanels.detail.insertAdjacentHTML('beforeend','<div id="expenseDetails"></div>');
financePanels.more.append(categoryCard);financePanels.more.insertAdjacentHTML('beforeend','<div id="financeExports" class="card"><h3>CSV 匯出</h3><p class="management-help">依支出紀錄／蝦子成本目前篩選匯出。報表匯出位於營業報表。</p></div>');$('financeExports').append(expenseExport,shrimpExport);financePanels.more.insertAdjacentHTML('beforeend','<h3>財務操作紀錄</h3>');financePanels.more.append(operations);
// Normal-flow actions never float over a keyboard or input.
for(const form of [purchaseForm,costForm]){const actions=document.createElement('div');actions.className='finance-form-actions';actions.append(form.querySelector('button.primary'),form.querySelector(form===purchaseForm?'#cancelExpense':'#cancelShrimp'));form.append(actions)}

function formSnapshot(form){return JSON.stringify([...form.querySelectorAll('input,select,textarea')].map(e=>[e.id||e.dataset.field||'confirmation',e.type==='checkbox'?e.checked:e.value]))}
function financeDirty(){return financeView==='purchase'&&!financeDraft?.completed&&formSnapshot(purchaseForm)!==purchaseBaseline||financeView==='shrimp'&&!shrimpDraft?.completed&&formSnapshot(costForm)!==shrimpBaseline}
function allowFinanceLeave(){if(!allowInventoryLeave())return false;if(busy){fail(Error('操作尚未完成，請稍候並確認結果'));return false}if(!financeDirty())return true;if(!confirm('尚有未儲存內容，確定放棄並離開？'))return false;if(financeView==='purchase')resetExpense();else resetShrimp();return true}
function renderFinanceView(view){financeView=view;for(const [key,panel] of Object.entries(financePanels))panel.classList.toggle('hidden',key!==view);expensePanel.dataset.financeView=view;renderExpenseHome()}
function applyFinanceRoute(route){if(route.page!=='inventory'&&inventoryView!=='home'){inventoryView='home';inventoryDraft=null;inventoryPending=null;inventoryNavigate('home',true)}financeRoute=route;document.querySelectorAll('.management-panel').forEach(p=>p.classList.toggle('hidden',p.id!=='panel-'+route.page));document.querySelectorAll('[data-page]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.page===route.page)));renderFinanceView(route.view||'home');refreshManagement();window.scrollTo(0,0)}
function financeNavigate(view='home',force=false,page='expenses',replace=false){if(!force&&!allowFinanceLeave())return false;const route={page,view,index:replace?financeRoute.index:financeRoute.index+1};try{history[replace?'replaceState':'pushState']({...history.state,shrimpFinance:route},'',page==='expenses'?'#expenses/'+view:location.pathname+location.search)}catch(_){}applyFinanceRoute(route);return true}
function resetFinanceNavigation(){if(typeof financePanels==='undefined')return;financeView='home';purchaseBaseline=formSnapshot(purchaseForm);shrimpBaseline=formSnapshot(costForm);financeRoute={page:'orders',view:'home',index:Number.isInteger(history.state?.shrimpFinance?.index)?history.state.shrimpFinance.index:0};try{history.replaceState({...history.state,shrimpFinance:financeRoute},'',location.pathname+location.search)}catch(_){}applyFinanceRoute(financeRoute)}
window.addEventListener('popstate',e=>{
 if(restoringFinanceHistory){restoringFinanceHistory=false;return}const target=e.state?.shrimpFinance||{page:'orders',view:'home',index:0};
 if(!allowFinanceLeave()){const delta=financeRoute.index-target.index;if(delta){restoringFinanceHistory=true;history.go(delta)}else try{history.replaceState({...history.state,shrimpFinance:financeRoute},'','#expenses/'+financeView)}catch(_){}return}applyFinanceRoute(target);
});
window.addEventListener('beforeunload',e=>{if(busy||financeDirty()||inventoryDirty()){e.preventDefault();e.returnValue=''}});
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>financeNavigate('home',false,b.dataset.page));
expensePanel.querySelectorAll('[data-finance-go]').forEach(b=>b.onclick=()=>financeNavigate(b.dataset.financeGo));
expensePanel.querySelectorAll('[data-finance-back]').forEach(b=>b.onclick=()=>financeNavigate('home'));
$('financeNewExpense').onclick=()=>{if(!allowFinanceLeave())return;resetExpense();financeNavigate('purchase',true)};

const resetExpenseBeforeMobile=resetExpense;resetExpense=function(){resetExpenseBeforeMobile();financeDraft.lastMode=$('expenseMode').value;financeDraft.detailedReady=false;financePanels.purchase.querySelector('header h2').textContent='新增支出';purchaseBaseline=formSnapshot(purchaseForm)};
const resetShrimpBeforeMobile=resetShrimp;resetShrimp=function(){resetShrimpBeforeMobile();shrimpBaseline=formSnapshot(costForm)};
$('cancelExpense').onclick=()=>{if(allowFinanceLeave()){resetExpense();financeNavigate('home',true)}};
$('cancelShrimp').onclick=()=>{if(allowFinanceLeave()){resetShrimp();financeNavigate('home',true)}};
$('expenseMode').onchange=()=>{
 const to=$('expenseMode').value,from=financeDraft.lastMode||'simple';if(to==='simple'&&from==='detailed'&&$('purchaseLines').children.length>1&&!confirm('改成簡單記帳後，本次儲存不保留多品項明細。確定切換？')){$('expenseMode').value='detailed';return}
 if(to==='detailed'&&!financeDraft.detailedReady){$('purchaseLines').textContent='';const amount=$('expenseAmount').value;let cents;try{if(amount)cents=C.scaled(amount,2)}catch(_){}addPurchaseLine({name:$('expenseTitle').value,categoryId:$('expenseCategory').value,subtotalCents:cents,amountBasis:amount?'manual':'calculated',shrimp:$('simpleShrimp').checked,weightMilliCatty:$('simpleWeight').value?Number($('simpleWeight').value)*1000:0},financeDraft.lineId);financeDraft.detailedReady=true;}
 if(to==='simple'&&from==='detailed'){try{const data={...purchaseDraftData(),mode:'detailed'},rows=[...$('purchaseLines').children];let sum=0;for(const row of rows)sum+=C.scaled(row.querySelector('[data-field="amount"]').value,2);$('expenseAmount').value=(sum/100).toFixed(2);$('expenseTitle').value=rows.length===1?rows[0].querySelector('[data-field="name"]').value:'多品項採購';if(rows[0])$('expenseCategory').value=rows[0].querySelector('[data-field="categoryId"]').value;}catch(_){} }
 financeDraft.lastMode=to;expenseMode();
};
