// Cancellation and returns preserve original order snapshots and payment fields.
// The entry is rendered with every shipped card; binding never depends on inline onclick text.
function uncollectedEligibility(id){
 const o=orders[id],inv=management.inventory||{},existing=management.deliveryExceptions?.cases?.[id];
 if(!o?.shipped)return {allowed:false,message:'只有已出貨訂單可以登記未取貨退回。'};
 if(!ready||!uid)return {allowed:false,message:'資料尚未完成同步，暫停登記；請等待同步完成。'};
 if(!connected)return {allowed:false,message:'目前網路未連線，暫停儲存；請恢復連線後重試。'};
 if(!inv.initializedAt)return {allowed:false,message:'庫存尚未完成期初盤點，暫停退回回庫。'};
 if(!inv.mappingMode)return {allowed:false,message:'庫存尚未完成實體品項對應，暫停退回回庫。'};
 const basis=C.returnBasis(management,id);
 if(!basis){if(!Object.keys(inventoryProducts()).length)return {allowed:false,message:'歷史訂單缺出貨快照，且沒有可核對的實體庫存品項，暫停回補。'};return {allowed:true,message:'歷史訂單缺原出貨快照：必須人工核對實體品項與原出貨包數，未確認前不能回補。'}}
 if(!Object.keys(basis).length||Object.entries(basis).some(([pid,q])=>!inv.items?.[pid]||!Number.isSafeInteger(q)||q<=0))return {allowed:false,message:'原出貨實體明細不完整或品項無法辨識，暫停回補，請先人工核對。'};
 if(!existing&&Object.entries(basis).every(([pid,q])=>q<=(inv.returned?.[id]?.[pid]||0)+(inv.disposed?.[id]?.[pid]||0)))return {allowed:false,message:'原出貨數量已全部退回或報廢，沒有剩餘可登記數量；請先核對既有退貨紀錄，勿重複回補。'};
 return {allowed:true,message:existing?'此訂單已有未取貨紀錄；此入口只查看／修正原紀錄，不新增一次。':'收到退回包裹後才登記。只有確認冷鏈安全的可販售數量才能回庫；一般退貨請用「退貨入庫」。'};
}
