function decorateInventoryOrders(){const inv=management.inventory||{};const pending={};for(const [id,o] of Object.entries(orders))if(!o.shipped&&!inv.orderStates?.[id]?.cancelled)for(const i of C.items(o)){const row=pending[i.productId]||={name:i.productName,n:0};row.n+=(+i.qty||0)+(+i.gift||0)}$('pending').innerHTML=Object.values(pending).map(p=>'<span>'+esc(p.name)+'｜未出貨 <b>'+p.n+'</b> 單位（包／組）</span>').join('')||'目前沒有未出貨品項';for(const card of $('rows').querySelectorAll('.order-card')){const id=card.dataset.orderId;if(!id||!orders[id])continue;const o=orders[id],state=inv.orderStates?.[id]||null,actions=card.querySelector('.card-actions');if(state?.cancelled){const p=document.createElement('p');p.className='danger';p.textContent='已取消（保留原訂單及收款；不自動退款）';card.append(p)}const failed=management.deliveryExceptions?.cases?.[id];if(failed){const p=document.createElement('p');p.className='uncollected-badge';p.textContent='未取貨退回 · '+failed.date+' · 回庫 '+failed.totalResell+' 包／報廢 '+failed.totalDiscard+' 包'+(o.paid?' · 已收款，請人工核對退款':' · 未收款，不等同正常待收款');card.append(p)}const remove=actions.querySelector('.danger');if(remove&&(o.shipped||inv.everShipped?.[id]||state)){remove.disabled=true;remove.textContent='歷史保留'}
 const cancel=document.createElement('button');cancel.type='button';cancel.textContent=state?.cancelled?'恢復接單':'取消訂單';cancel.onclick=()=>{if(!confirm(state?.cancelled?'確認恢復接單？不會自動出貨或改動收款。':'確認取消訂單？不刪除、不退款、不自動回補庫存；實際退回請另做退貨入庫。'))return;const key=operationId();guard(()=>writeInventory({kind:state?.cancelled?'reopen':'cancel',orderId:id,expected:o,expectedState:state,reason:'使用者確認'},key))};actions.append(cancel);
 if(o.shipped){const ret=document.createElement('button');ret.type='button';ret.textContent='退貨入庫';ret.onclick=()=>{try{openInventoryReturn(id)}catch(e){fail(e)}};actions.append(ret);const missed=document.createElement('button');missed.type='button';missed.className='uncollected-entry';missed.dataset.orderAction='uncollected';missed.textContent=failed?'未取貨退回（查看／修正）':'未取貨退回';actions.append(missed);const returned=inv.returned?.[id];if(returned){const p=document.createElement('p');p.textContent='已確認回庫 '+Object.values(returned).reduce((s,n)=>s+n,0)+' 包（原出貨與收款紀錄保留）';card.append(p)}}
 }}
