function openInventoryReturn(id){const order=orders[id];if(!order?.shipped)return;const inv=management.inventory||{},returned=inv.returned?.[id]||{},basis=inv.mappingMode?(inv.orderSnapshots?.[id]?.totals||inv.legacyReturnSnapshots?.[id]?.totals):C.quantities(order),manual=inv.mappingMode&&!basis;inventoryReturnDraft={orderId:id,expected:JSON.parse(JSON.stringify(order)),expectedState:inv.orderStates?.[id]?JSON.parse(JSON.stringify(inv.orderStates[id])):null,expectedReturned:JSON.parse(JSON.stringify(returned)),operation:operationId(),manual};$('inventoryReturnForm').reset();$('inventoryReturnLines').innerHTML=(manual?'<p class="danger">此為期初前歷史訂單，沒有原扣庫快照。請人工確認原出貨的實體品項與總包數；這是退貨時的人工聲明，不代表原始出貨紀錄。</p>':'')+Object.entries(manual?Object.fromEntries(Object.keys(inventoryProducts()).map(id=>[id,0])):basis).map(([pid,n])=>'<label>'+esc(inventoryProducts()[pid]?.name||pid)+(manual?'':('（可退 '+(n-(returned[pid]||0)-(inv.disposed?.[id]?.[pid]||0))+' 包）'))+(manual?'<br>人工確認原出貨總包數<input data-legacy-basis="'+esc(pid)+'" type="number" min="0" step="1" value="0">':'')+'<br>本次實際可販售回庫包數<input data-return-product="'+esc(pid)+'" type="number" min="0" '+(manual?'':'max="'+(n-(returned[pid]||0))+'"')+' step="1" value="0"></label>').join('');openActionDialog('inventoryReturnDialog')}
