$('inventoryReturnForm').onsubmit=e=>{e.preventDefault();guard(async()=>{const d=inventoryReturnDraft;if(!d)throw Error('請重新開啟退貨視窗');const quantities=Object.fromEntries([...document.querySelectorAll('[data-return-product]')].map(x=>[x.dataset.returnProduct,x.value]));await writeInventory({kind:'return',orderId:d.orderId,expected:d.expected,expectedState:d.expectedState,expectedReturned:d.expectedReturned,quantities,confirmed:$('inventoryReturnConfirmed').checked,...(d.manual?{confirmedLegacyBasis:$('inventoryReturnConfirmed').checked,legacyBasis:Object.fromEntries([...document.querySelectorAll('[data-legacy-basis]')].map(x=>[x.dataset.legacyBasis,x.value]))}:{}),reason:$('inventoryReturnReason').value},d.operation);closeActionDialog('inventoryReturnDialog');inventoryReturnDraft=null;$('inventoryNotice').textContent='退貨入庫已儲存；訂單金額與收款未改動'})};


