function openRiskDialog(id){try{if(busy)throw Error('前次操作尚未完成');if(customerEditorDirty)throw Error('請先儲存或關閉客戶基本資料的修改');const c=customerStats().find(c=>c.id===id);if(!c)throw Error('客戶已變更');const snapshot=C.customerRiskSnapshot(management,id);customerRiskDraft={customerId:id,active:!c.blacklisted,expectedSources:snapshot.sources,expectedRecords:JSON.parse(JSON.stringify(snapshot.records)),operation:operationId()};customerRiskPending=null;$('customerRiskForm').reset();$('customerRiskTitle').textContent=c.blacklisted?'解除黑名單':'加入黑名單';$('customerRiskPreview').textContent=c.name+' · ID '+id+' · '+c.effectiveCount+' 筆有效單 · 未取貨 '+c.failedCount+' 次。'+(c.blacklisted?'將解除此歸戶範圍內的 '+c.blacklistRecords.length+' 個有效標記，歷史全部保留。':'只加警告標記，不拒絕下單、不修改訂單。')+(c.identityWarnings.length?' 請注意：'+c.identityWarnings.join('；'):'');openActionDialog('customerRiskDialog')}catch(e){fail(e)}}
